{
  "contract": "WAsgard",
  "closure": {
    "site_function": "wrap",
    "site_call": ".transferFrom",
    "functions": [
      "wrap",
      "claimDividends",
      "claimInactiveAccountDividends"
    ],
    "justification": "These functions interact with the 'deposits' storage variable, which is exposed during the callback in 'wrap'."
  },
  "protocol": {
    "during_phase": "exposed",
    "allowed_callbacks": [
      "wrap",
      "claimDividends",
      "claimInactiveAccountDividends"
    ],
    "nesting_bound": {
      "wrap": 1
    }
  },
  "phases": {
    "function": "wrap",
    "pre": {
      "name": "pre",
      "from_marker": "start",
      "to_marker": "before_transferFrom"
    },
    "exposed": {
      "name": "exposed",
      "from_marker": "before_transferFrom",
      "to_marker": "after_transferFrom"
    },
    "post": {
      "name": "post",
      "from_marker": "after_transferFrom",
      "to_marker": "end"
    },
    "linearization_point": "after_transferFrom"
  },
  "ghost_state": [
    {
      "name": "inFlight",
      "sol_type": "uint256",
      "meaning": "Tracks the amount in-flight during the callback window.",
      "backed_by_storage": false
    }
  ],
  "exposure_invariant": {
    "formula": "_sum__balances == _totalSupply + inFlight",
    "stable_formula": "_sum__balances == _totalSupply",
    "kind": "conserve"
  },
  "composition": {
    "target_property": "_sum__balances == _totalSupply",
    "rule": "The exposure invariant ensures that the total supply is conserved across the callback window, accounting for any in-flight changes."
  }
}
